    def __init__(self, seed: int | None = None):
        super().__init__(seed=seed)

    def opening_action(self, game, grid, rows, cols):
        center_r = rows // 2
        center_c = cols // 2
        return ('reveal', center_r, center_c)

    def neighbor_positions(self, game, r, c, rows, cols):
        return game.board.neighbors(r, c)

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if cell.is_revealed:
            return cell.adjacent_mines
        return None

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        rows, cols = game.get_config().rows, game.get_config().cols

        is_corner = (r in (0, rows - 1)) and (c in (0, cols - 1))
        is_edge = (r in (0, rows - 1)) or (c in (0, cols - 1))

        prob = prob_map.get(pos, Fraction(0))

        neighbor_revealed_count = sum(
            1 for nr, nc in neighbors_of.get(pos, [])
            if game.get_cell(nr, nc).is_revealed
        )
        neighbor_bonus = Fraction(neighbor_revealed_count, 1)

        if is_corner:
            corner_penalty = Fraction(1, 2)
        elif is_edge:
            corner_penalty = Fraction(1, 4)
        else:
            corner_penalty = Fraction(0, 1)

        adjusted_prob = prob + corner_penalty - neighbor_bonus * Fraction(1, 8)
        adjusted_prob = max(Fraction(0, 1), min(Fraction(1, 1), adjusted_prob))

        return (adjusted_prob, pos)

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        config = game.get_config()
        total_unrevealed = sum(
            1 for r in range(config.rows)
            for c in range(config.cols)
            if not game.get_cell(r, c).is_revealed
        )

        total_flagged = sum(
            1 for r in range(config.rows)
            for c in range(config.cols)
            if game.get_cell(r, c).is_flagged
        )

        remaining_mines = config.mine_count - total_flagged

        if total_unrevealed > 0 and remaining_mines > 0:
            global_mine_density = Fraction(remaining_mines, total_unrevealed)

            for pos in prob_map:
                if prob_map[pos] < global_mine_density * Fraction(1, 2):
                    prob_map[pos] = prob_map[pos] * Fraction(9, 10)

        return prob_map

