class CanonicalStandardMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed: int | None = None):
        super().__init__(seed=seed)

    def opening_action(self, game, grid, rows, cols):
        center_r = rows // 2
        center_c = cols // 2
        return ('reveal', center_r, center_c)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        cell = grid[r][c]

        if cell.is_revealed:
            clue = cell.adjacent_mines
            if clue is None or clue == 0:
                return (float('inf'), 0)

            unrevealed_neighbors = [n for n in neighbors_of[pos] if not grid[n[0]][n[1]].is_revealed]
            if not unrevealed_neighbors:
                return (float('inf'), 0)

            flagged_count = sum(1 for nr, nc in unrevealed_neighbors if grid[nr][nc].is_flagged)
            remaining = clue - flagged_count

            if remaining == 0:
                return (0, len(unrevealed_neighbors))
            if remaining == len(unrevealed_neighbors):
                return (float('inf'), -len(unrevealed_neighbors))

            prob_sum = sum(prob_map.get((nr, nc), Fraction(0)) for nr, nc in unrevealed_neighbors)
            constraint_tightness = Fraction(remaining) / Fraction(max(1, len(unrevealed_neighbors)))

            return (float(constraint_tightness), float(prob_sum))

        prob = prob_map.get(pos, Fraction(0))
        neighbor_clues = sum(1 for nr, nc in neighbors_of[pos] if grid[nr][nc].is_revealed and grid[nr][nc].adjacent_mines and grid[nr][nc].adjacent_mines > 0)

        return (float(prob), -neighbor_clues)

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        config = game.get_config()
        total_mines = config.mine_count

        unrevealed_positions = [pos for r in range(config.rows) for c in range(config.cols) 
                                if not grid[r][c].is_revealed for pos in [(r, c)]]

        flagged_count = sum(1 for r in range(config.rows) for c in range(config.cols) if grid[r][c].is_flagged)
        remaining_mines = total_mines - flagged_count

        if remaining_mines <= 0:
            return prob_map

        current_sum = sum(prob_map.get(pos, Fraction(0)) for pos in unrevealed_positions)

        if current_sum == 0:
            uniform_prob = Fraction(remaining_mines, max(1, len(unrevealed_positions)))
            for pos in unrevealed_positions:
                prob_map[pos] = uniform_prob
        elif current_sum != remaining_mines:
            scale = Fraction(remaining_mines) / current_sum if current_sum > 0 else Fraction(1)
            for pos in unrevealed_positions:
                if pos in prob_map:
                    prob_map[pos] = prob_map[pos] * scale

        return prob_map

