class CascadeAwarePAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed: int | None = None):
        super().__init__(seed=seed)

    def opening_action(self, game, grid, rows, cols):
        config = game.get_config()
        if config.safe_first_click:
            mid_r, mid_c = rows // 2, cols // 2
            return ("reveal", mid_r, mid_c)
        return ("reveal", 0, 0)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        cell = game.get_cell(r, c)

        if cell.is_revealed:
            return (float('inf'), 0)

        if cell.is_flagged:
            return (float('inf'), 0)

        mine_prob = prob_map.get(pos, Fraction(0))
        safe_prob = 1 - mine_prob

        zero_neighbors = 0
        for nr, nc in neighbors_of.get(pos, []):
            neighbor_cell = game.get_cell(nr, nc)
            if neighbor_cell.is_revealed and neighbor_cell.adjacent_mines == 0:
                zero_neighbors += 1

        cascade_bonus = zero_neighbors * 2

        uncertainty = float(mine_prob * safe_prob) if mine_prob != 0 else 0.0

        score = float(safe_prob) + cascade_bonus

        return (score, uncertainty)

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows, cols = len(grid), len(grid[0])

        zero_cells = []
        for r in range(rows):
            for c in range(cols):
                cell = game.get_cell(r, c)
                if cell.is_revealed and cell.adjacent_mines == 0:
                    zero_cells.append((r, c))

        affected = set()
        for zr, zc in zero_cells:
            for nr, nc in game.board.neighbors(zr, zc):
                if (nr, nc) not in affected:
                    neighbor_cell = game.get_cell(nr, nc)
                    if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                        affected.add((nr, nc))

        for pos in affected:
            if pos in prob_map:
                prob_map[pos] = Fraction(0)

        return prob_map

