        if cell.is_revealed:
            neighbors = game.board.neighbors(r, c)
            unrevealed = [n for n in neighbors if not game.get_cell(n[0], n[1]).is_revealed]
            constraint_strength = float(len(unrevealed)) if unrevealed else 0.0

        score = float(base_prob) + perimeter_bonus + constraint_strength * 0.5
