    def __init__(self, seed: int | None = None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c) -> int | None:
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        return cell.adjacent_mines

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of) -> tuple:
        r, c = pos
        cell = grid[r][c]

        if not cell.is_revealed:
            return (0, 0, 0)

        distance = cell.adjacent_mines
        if distance is None or distance < 0:
            return (0, 0, 0)

        revealed_neighbors = []
        unrevealed_neighbors = []

        for nr, nc in neighbors_of.get(pos, []):
            neighbor = grid[nr][nc]
            if neighbor.is_revealed:
                revealed_neighbors.append((nr, nc))
            elif not neighbor.is_flagged:
                unrevealed_neighbors.append((nr, nc))

        if not unrevealed_neighbors:
            return (0, 0, 0)

        safe_count = sum(1 for nr, nc in unrevealed_neighbors if prob_map.get((nr, nc), Fraction(0)) == 0)
        if safe_count > 0:
            return (1000 + safe_count, 0, 0)

        mine_count = sum(1 for nr, nc in unrevealed_neighbors if prob_map.get((nr, nc), Fraction(0)) > 0)
        if mine_count == 0:
