        constraint_strength = abs(distance - sum(1 for nr, nc in revealed_neighbors if grid[nr][nc].is_mine))
        constraint_strength = max(1, constraint_strength)

        risk_penalty = float(avg_prob) * 2.0

        return (constraint_strength - risk_penalty, float(avg_prob), len(unrevealed_neighbors))

